<?php require_once __DIR__.'/components.php'; metric_cards(); $sort=is_string($_GET['sort'] ?? null)?$_GET['sort']:'goals'; ?>
<section class="panel mt-4"><?php section_heading('Player statistics'); ?><p class="panel-subtitle">Chỉ tính các trận Completed. Chọn tiêu đề cột để sắp xếp.</p><div class="table-responsive"><table class="table"><thead><tr><th>#</th><th>Player</th><?php foreach(['played'=>'Matches','goals'=>'Goals','assists'=>'Assists','contributions'=>'G+A'] as $key=>$label): ?><th><a href="<?= url('statistics',['sort'=>$key]) ?>"><?= $label ?> <?= $sort===$key?'↓':'↕' ?></a></th><?php endforeach; ?></tr></thead><tbody><?php foreach(rankings($sort) as $i=>$p): ?><tr><td><?= $i+1 ?></td><td><a class="table-player" href="<?= url('profile',['id'=>$p['id']]) ?>"><?= avatar($p) ?><span><?= e($p['full_name']) ?><small>#<?= e($p['jersey_number']) ?></small></span></a></td><td><?= e($p['played']) ?></td><td><strong><?= e($p['goals']) ?></strong></td><td><?= e($p['assists']) ?></td><td><?= e($p['contributions']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
